const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  HeadingLevel, AlignmentType, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, NumberFormat
} = require('/home/claude/.npm-global/lib/node_modules/docx');
const fs = require('fs');

const GOLD = "B8860B";
const DARK = "1A1A2E";
const LIGHT_GOLD = "FFF8E7";
const MID_GOLD = "F5E6C8";
const WHITE = "FFFFFF";
const GRAY = "F7F7F7";

const border = { style: BorderStyle.SINGLE, size: 1, color: "D4AF37" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 360, after: 160 },
    children: [new TextRun({ text, font: "Arial", size: 32, bold: true, color: DARK })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 280, after: 120 },
    children: [new TextRun({ text, font: "Arial", size: 26, bold: true, color: GOLD })]
  });
}

function h3(text) {
  return new Paragraph({
    spacing: { before: 200, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 22, bold: true, color: DARK })]
  });
}

function body(text, options = {}) {
  return new Paragraph({
    spacing: { before: 60, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333", ...options })]
  });
}

function bullet(text, bold = false) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { before: 40, after: 40 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333", bold })]
  });
}

function numbered(text) {
  return new Paragraph({
    numbering: { reference: "numbers", level: 0 },
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: "333333" })]
  });
}

function spacer(size = 160) {
  return new Paragraph({ spacing: { before: size, after: 0 }, children: [new TextRun("")] });
}

function divider() {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "D4AF37", space: 1 } },
    children: [new TextRun("")]
  });
}

function labelValue(label, value) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [
      new TextRun({ text: label + ": ", font: "Arial", size: 22, bold: true, color: DARK }),
      new TextRun({ text: value, font: "Arial", size: 22, color: "333333" })
    ]
  });
}

function calloutBox(title, lines) {
  const cellChildren = [
    new Paragraph({
      spacing: { before: 80, after: 60 },
      children: [new TextRun({ text: title, font: "Arial", size: 22, bold: true, color: DARK })]
    }),
    ...lines.map(l => new Paragraph({
      numbering: { reference: "bullets", level: 0 },
      spacing: { before: 40, after: 40 },
      children: [new TextRun({ text: l, font: "Arial", size: 22, color: "333333" })]
    }))
  ];
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders,
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 240, right: 240 },
        children: cellChildren
      })]
    })]
  });
}

function twoColTable(col1Items, col2Items, col1Header, col2Header) {
  const headerRow = new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: DARK, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 160 },
        children: [new Paragraph({ children: [new TextRun({ text: col1Header, font: "Arial", size: 22, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: DARK, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 160 },
        children: [new Paragraph({ children: [new TextRun({ text: col2Header, font: "Arial", size: 22, bold: true, color: WHITE })] })]
      })
    ]
  });

  const maxLen = Math.max(col1Items.length, col2Items.length);
  const dataRows = Array.from({ length: maxLen }, (_, i) => new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: i % 2 === 0 ? WHITE : GRAY, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 160, right: 160 },
        children: [new Paragraph({ children: [new TextRun({ text: col1Items[i] || "", font: "Arial", size: 22, color: "333333" })] })]
      }),
      new TableCell({
        borders,
        width: { size: 4680, type: WidthType.DXA },
        shading: { fill: i % 2 === 0 ? WHITE : GRAY, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 160, right: 160 },
        children: [new Paragraph({ children: [new TextRun({ text: col2Items[i] || "", font: "Arial", size: 22, color: "333333" })] })]
      })
    ]
  }));

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: [headerRow, ...dataRows]
  });
}

function pricingTable() {
