    ["Tier", "Deliverable", "Price"],
    ["Starter", "Written analysis only, 1 call under 30 min", "$75 - $150"],
    ["Standard", "Full written report, objection rewrites, follow-up message", "$250 - $500"],
    ["Premium", "Report + Loom walkthrough + rewritten script sections + SOP suggestions", "$750 - $1,500"],
    ["Revenue Leak Conversion Audit", "Multi-call review, full sales process analysis, booking flow, follow-up systems, conversion fixes", "$1,500 - $5,000"],
  ];

  const headerRow = new TableRow({
    children: rows[0].map((h, i) => new TableCell({
      borders,
      width: { size: i === 0 ? 2200 : i === 1 ? 5000 : 2160, type: WidthType.DXA },
      shading: { fill: DARK, type: ShadingType.CLEAR },
      margins: { top: 100, bottom: 100, left: 160, right: 160 },
      children: [new Paragraph({ children: [new TextRun({ text: h, font: "Arial", size: 22, bold: true, color: WHITE })] })]
    }))
  });

  const dataRows = rows.slice(1).map((row, ri) => new TableRow({
    children: row.map((cell, ci) => new TableCell({
      borders,
      width: { size: ci === 0 ? 2200 : ci === 1 ? 5000 : 2160, type: WidthType.DXA },
      shading: { fill: ri % 2 === 0 ? WHITE : GRAY, type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 160, right: 160 },
      children: [new Paragraph({ children: [new TextRun({ text: cell, font: "Arial", size: 22, color: ri === 3 ? GOLD : "333333", bold: ri === 3 })] })]
    }))
  }));

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2200, 5000, 2160],
    rows: [headerRow, ...dataRows]
  });
}

